// swift-tools-version: 6.0
// StarSI iOS — the interface and the phone-side MCP host.
//
// Library targets are platform-agnostic Swift so they can be unit-tested
// on macOS. The app shell lives in Sources/StarSIApp and is wrapped in an
// Xcode project generated by XcodeGen from project.yml (not committed).

import PackageDescription

let package = Package(
    name: "StarSI",
    platforms: [.iOS(.v18), .macOS(.v15)],
    products: [
        .library(name: "StarSIClient", targets: ["StarSIClient"]),
        .library(name: "StarSIMCP", targets: ["StarSIMCP"]),
    ],
    dependencies: [
        // Official Swift MCP SDK. Pin once the API settles.
        .package(url: "https://github.com/modelcontextprotocol/swift-sdk.git", from: "0.9.0"),
    ],
    targets: [
        .target(
            name: "StarSIClient",
            path: "Sources/StarSIClient"
        ),
        .target(
            name: "StarSIMCP",
            dependencies: [
                .product(name: "MCP", package: "swift-sdk"),
            ],
            path: "Sources/StarSIMCP"
        ),
        .testTarget(
            name: "StarSIClientTests",
            dependencies: ["StarSIClient"],
            path: "Tests/StarSIClientTests"
        ),
    ]
)
